node -e "
const AdmZip = require('/tmp/node_modules/node_modules/adm-zip');
const zip = new AdmZip('/workspace/testbed/docs/customer_report.docx');
const xml = zip.readAsText('word/document.xml');

// Parse tables and paragraphs properly
const lines = [];
// Split by paragraph
const paragraphs = xml.split(/<\/w:p>/g);
for (const p of paragraphs) {
  // Check if it's a table cell end
  const texts = [];
  const runs = p.match(/<w:t[^>]*>([^<]*)<\/w:t>/g) || [];
  for (const r of runs) {
    const match = r.match(/<w:t[^>]*>([^<]*)<\/w:t>/);
    if (match) texts.push(match[1]);
  }
  if (texts.length > 0) {
    lines.push(texts.join(''));
  } else if (p.match(/<w:p[\s>]/) && !p.match(/<w:tc/)) {
    lines.push('');
  }
}
console.log(lines.join('\n'));
"
